'use strict';

// ============================================================================
// Content model - data-access layer for editable marketing pages (Phase 13).
// ----------------------------------------------------------------------------
// A content_page row backs a public marketing route like /about or /faq. The
// public surface only ever returns published rows; the admin surface returns
// drafts too. Slug format is enforced by a CHECK constraint at the database
// level; lengths and OG URL shape are enforced in the controller layer.
// ============================================================================

const { query, queryOne } = require('../db/query');

const COLUMNS =
  'id, slug, title, body_markdown, meta_description, meta_og_image_url, ' +
  'is_published, published_at, created_at, updated_at';

// Single page lookup by slug. opts.includeDrafts skips the is_published gate;
// the controller passes true only for staff-facing reads.
async function findBySlug(slug, opts) {
  opts = opts || {};
  let sql = 'SELECT ' + COLUMNS + ' FROM content_pages WHERE slug = $1';
  if (!opts.includeDrafts) {
    sql += ' AND is_published = TRUE';
  }
  return queryOne(sql, [slug]);
}

// All pages, newest-first, hard-capped at 200. filters.isPublished narrows.
async function findAll(filters) {
  filters = filters || {};
  const where = [];
  const params = [];
  if (typeof filters.isPublished === 'boolean') {
    params.push(filters.isPublished);
    where.push('is_published = $' + params.length);
  }
  const sql =
    'SELECT ' + COLUMNS + ' FROM content_pages' +
    (where.length ? ' WHERE ' + where.join(' AND ') : '') +
    ' ORDER BY updated_at DESC LIMIT 200';
  const result = await query(sql, params);
  return result.rows;
}

// Create a draft page. Caller validates field shape; the DB CHECK enforces
// slug format as a last line of defense.
async function create(data) {
  return queryOne(
    'INSERT INTO content_pages ' +
      '(slug, title, body_markdown, meta_description, meta_og_image_url, ' +
      ' is_published, published_at) ' +
      'VALUES ($1, $2, $3, $4, $5, $6, $7) ' +
      'RETURNING ' + COLUMNS,
    [
      data.slug,
      data.title,
      data.bodyMarkdown || '',
      data.metaDescription || null,
      data.metaOgImageUrl || null,
      data.isPublished === true,
      data.isPublished === true ? new Date() : null,
    ]
  );
}

// Dynamic SET-list update (B1/B2 lesson). Key absent means "leave alone";
// key present with empty string on metaDescription/metaOgImageUrl means
// "clear to null". is_published flips go through publish/unpublish.
async function update(slug, data) {
  const sets = [];
  const params = [];
  function bind(column, jsKey, transform) {
    if (Object.prototype.hasOwnProperty.call(data, jsKey)) {
      const raw = data[jsKey];
      const value = typeof transform === 'function' ? transform(raw) : raw;
      params.push(value);
      sets.push(column + ' = $' + params.length);
    }
  }
  bind('slug', 'slug');
  bind('title', 'title');
  bind('body_markdown', 'bodyMarkdown');
  bind('meta_description', 'metaDescription', function (v) {
    return typeof v === 'string' && v.trim() === '' ? null : v;
  });
  bind('meta_og_image_url', 'metaOgImageUrl', function (v) {
    return typeof v === 'string' && v.trim() === '' ? null : v;
  });
  if (sets.length === 0) {
    return findBySlug(slug, { includeDrafts: true });
  }
  params.push(slug);
  const sql =
    'UPDATE content_pages SET ' + sets.join(', ') +
    ' WHERE slug = $' + params.length +
    ' RETURNING ' + COLUMNS;
  return queryOne(sql, params);
}

// Flip is_published=true and stamp published_at. Idempotent over already-
// published rows so a repeated POST is a no-op rather than an error.
async function publish(slug) {
  return queryOne(
    'UPDATE content_pages SET is_published = TRUE, ' +
      'published_at = COALESCE(published_at, now()) ' +
      'WHERE slug = $1 RETURNING ' + COLUMNS,
    [slug]
  );
}

// Flip is_published=false. published_at is intentionally left intact for
// history so unpublish then republish does not reset the original date.
async function unpublish(slug) {
  return queryOne(
    'UPDATE content_pages SET is_published = FALSE ' +
      'WHERE slug = $1 RETURNING ' + COLUMNS,
    [slug]
  );
}

module.exports = {
  findBySlug: findBySlug,
  findAll: findAll,
  create: create,
  update: update,
  publish: publish,
  unpublish: unpublish,
};

'use strict';

// ============================================================================
// Content controller - public + admin marketing pages (Phase 13).
// ----------------------------------------------------------------------------
//   GET    /api/content/:slug                       - public read (published)
//   GET    /api/admin/content                       - staff list (all)
//   GET    /api/admin/content/:slug                 - staff read (drafts ok)
//   POST   /api/admin/content                       - staff create
//   PATCH  /api/admin/content/:slug                 - staff update
//   POST   /api/admin/content/:slug/publish         - staff publish
//   POST   /api/admin/content/:slug/unpublish       - staff unpublish
//
// The public getPublic route is intentionally anonymous so search engines
// can crawl content; that is the entire point of this feature. There is no
// audit row for it (anonymous traffic + no PHI). Admin routes audit every
// view/edit with phiAccessed=false (marketing copy is not PHI).
// ============================================================================

const contentModel = require('../models/content.model');
const audit = require('../services/audit.service');
const errors = require('../utils/errors');

const SLUG_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const MAX_SLUG_LEN = 64;
const MAX_TITLE_LEN = 200;
const MAX_BODY_LEN = 100000;
const MAX_META_DESC_LEN = 300;
const MAX_OG_URL_LEN = 2048;

function requestMeta(req) {
  return { ipAddress: req.ip, userAgent: req.get('user-agent') || null };
}

function present(row) {
  if (!row) return null;
  return {
    id: row.id,
    slug: row.slug,
    title: row.title,
    bodyMarkdown: row.body_markdown,
    metaDescription: row.meta_description,
    metaOgImageUrl: row.meta_og_image_url,
    isPublished: row.is_published,
    publishedAt: row.published_at,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

// Trim a string to a normalized form. Returns '' for non-strings.
function normStr(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function isValidSlug(value) {
  return (
    typeof value === 'string' &&
    value.length > 0 &&
    value.length <= MAX_SLUG_LEN &&
    SLUG_RE.test(value)
  );
}

// Accept http(s) URLs only. Empty/null/undefined is allowed (means "no
// OG image"). Anything else is rejected.
function isValidHttpUrl(value) {
  if (value === null || value === undefined) return true;
  if (typeof value !== 'string') return false;
  const trimmed = value.trim();
  if (trimmed === '') return true;
  if (trimmed.length > MAX_OG_URL_LEN) return false;
  try {
    const u = new URL(trimmed);
    return u.protocol === 'http:' || u.protocol === 'https:';
  } catch (_) {
    return false;
  }
}

// GET /api/content/:slug - public, anonymous, no audit.
async function getPublic(req, res, next) {
  try {
    const slug = normStr(req.params.slug);
    if (!isValidSlug(slug)) {
      return next(errors.badRequest('That Content Reference Is Not Valid.'));
    }
    const row = await contentModel.findBySlug(slug);
    if (!row) {
      return next(errors.notFound('Page Not Found.'));
    }
    res.status(200).json({
      page: {
        slug: row.slug,
        title: row.title,
        bodyMarkdown: row.body_markdown,
        metaDescription: row.meta_description,
        metaOgImageUrl: row.meta_og_image_url,
        publishedAt: row.published_at,
        updatedAt: row.updated_at,
      },
    });
  } catch (err) {
    next(err);
  }
}

// GET /api/admin/content - staff list, drafts included.
async function listAdmin(req, res, next) {
  try {
    const rows = await contentModel.findAll();
    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'content.admin.list.viewed',
      entityType: 'content_page',
      entityId: null,
      phiAccessed: false,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { count: rows.length },
    });
    res.status(200).json({ pages: rows.map(present) });
  } catch (err) {
    next(err);
  }
}

// GET /api/admin/content/:slug - staff read, drafts ok.
async function adminGet(req, res, next) {
  try {
    const slug = normStr(req.params.slug);
    if (!isValidSlug(slug)) {
      return next(errors.badRequest('That Content Reference Is Not Valid.'));
    }
    const row = await contentModel.findBySlug(slug, { includeDrafts: true });
    if (!row) {
      return next(errors.notFound('Page Not Found.'));
    }
    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'content.admin.viewed',
      entityType: 'content_page',
      entityId: row.id,
      phiAccessed: false,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
    });
    res.status(200).json({ page: present(row) });
  } catch (err) {
    next(err);
  }
}

// POST /api/admin/content - staff create.
async function adminCreate(req, res, next) {
  try {
    const body = req.body || {};
    const slug = normStr(body.slug);
    if (!isValidSlug(slug)) {
      return next(errors.badRequest('A Valid Slug Is Required (Lowercase Letters, Digits, Hyphens).'));
    }
    const title = normStr(body.title);
    if (title.length === 0 || title.length > MAX_TITLE_LEN) {
      return next(errors.badRequest('A Valid Title Is Required.'));
    }
    const bodyMarkdown = typeof body.bodyMarkdown === 'string' ? body.bodyMarkdown : '';
    if (bodyMarkdown.length > MAX_BODY_LEN) {
      return next(errors.badRequest('The Body Is Too Long.'));
    }
    let metaDescription = null;
    if (typeof body.metaDescription === 'string') {
      const trimmed = body.metaDescription.trim();
      if (trimmed.length > MAX_META_DESC_LEN) {
        return next(errors.badRequest('The Meta Description Is Too Long.'));
      }
      metaDescription = trimmed === '' ? null : trimmed;
    }
    if (!isValidHttpUrl(body.metaOgImageUrl)) {
      return next(errors.badRequest('The OG Image URL Is Not Valid.'));
    }
    const ogUrl =
      typeof body.metaOgImageUrl === 'string' && body.metaOgImageUrl.trim() !== ''
        ? body.metaOgImageUrl.trim()
        : null;

    const created = await contentModel.create({
      slug: slug,
      title: title,
      bodyMarkdown: bodyMarkdown,
      metaDescription: metaDescription,
      metaOgImageUrl: ogUrl,
      isPublished: body.isPublished === true,
    });

    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'content.admin.created',
      entityType: 'content_page',
      entityId: created.id,
      phiAccessed: false,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { slug: created.slug },
    });
    res.status(201).json({ page: present(created) });
  } catch (err) {
    next(err);
  }
}

// PATCH /api/admin/content/:slug - staff update.
async function adminUpdate(req, res, next) {
  try {
    const slug = normStr(req.params.slug);
    if (!isValidSlug(slug)) {
      return next(errors.badRequest('That Content Reference Is Not Valid.'));
    }
    const body = req.body || {};
    const data = {};

    if (typeof body.slug === 'string') {
      const newSlug = body.slug.trim();
      if (!isValidSlug(newSlug)) {
        return next(errors.badRequest('A Valid Slug Is Required (Lowercase Letters, Digits, Hyphens).'));
      }
      data.slug = newSlug;
    }
    if (typeof body.title === 'string') {
      const t = body.title.trim();
      if (t.length === 0 || t.length > MAX_TITLE_LEN) {
        return next(errors.badRequest('A Valid Title Is Required.'));
      }
      data.title = t;
    }
    if (typeof body.bodyMarkdown === 'string') {
      if (body.bodyMarkdown.length > MAX_BODY_LEN) {
        return next(errors.badRequest('The Body Is Too Long.'));
      }
      data.bodyMarkdown = body.bodyMarkdown;
    }
    if (typeof body.metaDescription === 'string') {
      const trimmed = body.metaDescription.trim();
      if (trimmed.length > MAX_META_DESC_LEN) {
        return next(errors.badRequest('The Meta Description Is Too Long.'));
      }
      // Clear-semantics: empty string clears to null.
      data.metaDescription = trimmed;
    }
    if (Object.prototype.hasOwnProperty.call(body, 'metaOgImageUrl')) {
      if (!isValidHttpUrl(body.metaOgImageUrl)) {
        return next(errors.badRequest('The OG Image URL Is Not Valid.'));
      }
      data.metaOgImageUrl =
        typeof body.metaOgImageUrl === 'string' ? body.metaOgImageUrl.trim() : '';
    }

    // Block is_published flips via PATCH; publish/unpublish endpoints own that.
    if (Object.prototype.hasOwnProperty.call(body, 'isPublished')) {
      return next(errors.badRequest('Use The Publish Or Unpublish Action To Change Publication State.'));
    }

    const current = await contentModel.findBySlug(slug, { includeDrafts: true });
    if (!current) {
      return next(errors.notFound('Page Not Found.'));
    }
    const updated = await contentModel.update(slug, data);
    if (!updated) {
      return next(errors.notFound('Page Not Found.'));
    }

    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'content.admin.updated',
      entityType: 'content_page',
      entityId: updated.id,
      phiAccessed: false,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { slug: updated.slug },
    });
    res.status(200).json({ page: present(updated) });
  } catch (err) {
    next(err);
  }
}

// POST /api/admin/content/:slug/publish
async function adminPublish(req, res, next) {
  try {
    const slug = normStr(req.params.slug);
    if (!isValidSlug(slug)) {
      return next(errors.badRequest('That Content Reference Is Not Valid.'));
    }
    const current = await contentModel.findBySlug(slug, { includeDrafts: true });
    if (!current) {
      return next(errors.notFound('Page Not Found.'));
    }
    const updated = await contentModel.publish(slug);
    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'content.admin.published',
      entityType: 'content_page',
      entityId: updated.id,
      phiAccessed: false,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { slug: updated.slug },
    });
    res.status(200).json({ page: present(updated) });
  } catch (err) {
    next(err);
  }
}

// POST /api/admin/content/:slug/unpublish
async function adminUnpublish(req, res, next) {
  try {
    const slug = normStr(req.params.slug);
    if (!isValidSlug(slug)) {
      return next(errors.badRequest('That Content Reference Is Not Valid.'));
    }
    const current = await contentModel.findBySlug(slug, { includeDrafts: true });
    if (!current) {
      return next(errors.notFound('Page Not Found.'));
    }
    const updated = await contentModel.unpublish(slug);
    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'content.admin.unpublished',
      entityType: 'content_page',
      entityId: updated.id,
      phiAccessed: false,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { slug: updated.slug },
    });
    res.status(200).json({ page: present(updated) });
  } catch (err) {
    next(err);
  }
}

module.exports = {
  getPublic: getPublic,
  listAdmin: listAdmin,
  adminGet: adminGet,
  adminCreate: adminCreate,
  adminUpdate: adminUpdate,
  adminPublish: adminPublish,
  adminUnpublish: adminUnpublish,
};

'use strict';

// ============================================================================
// Public routes: anonymous, no auth, intentionally crawlable.
// ----------------------------------------------------------------------------
// Phase 13: editable content pages (About, How It Works, Safety, FAQ, etc.).
// The whole point of this surface is that search engines can fetch it without
// a token, so authenticate is deliberately not mounted here.
// ============================================================================

const express = require('express');
const contentController = require('../controllers/content.controller');

const router = express.Router();

// Phase 13: public content pages. No authenticate middleware - these
// routes are intentionally anonymous so search engines can crawl.
router.get('/:slug', contentController.getPublic);

module.exports = router;

'use strict';

// ============================================================================
// Admin routes: the staff operations dashboard and audit-log review.
// Every endpoint requires a valid access token and the admin or support role;
// authorize() runs after authenticate so it can read req.user.role.
// ============================================================================

const express = require('express');

const adminController = require('../controllers/admin.controller');
const couponController = require('../controllers/coupon.controller');
const catalogController = require('../controllers/catalog.controller');
const providerProfileController = require('../controllers/provider-profile.controller');
const visitController = require('../controllers/visit.controller');
const labController = require('../controllers/lab.controller');
const urgentController = require('../controllers/urgent.controller');
const dependentController = require('../controllers/dependent.controller');
const contentController = require('../controllers/content.controller');
const authenticate = require('../middleware/authenticate');
const authorize = require('../middleware/authorize');
const validate = require('../middleware/validate');
const {
  createCouponSchema,
  updateCouponSchema,
} = require('../validators/coupon.validator');

const router = express.Router();

// Staff-only: every admin route is gated to the admin and support roles.
const staffOnly = [authenticate, authorize('admin', 'support')];

// Platform operations overview.
router.get('/dashboard', staffOnly, adminController.dashboard);

// Recent audit-log entries for compliance review.
router.get('/audit-log', staffOnly, adminController.auditLog);

// Coupon management: list every coupon, create one, update its mutable terms.
router.get('/coupons', staffOnly, couponController.listCoupons);
router.post(
  '/coupons',
  staffOnly,
  validate(createCouponSchema),
  couponController.createCoupon
);
router.patch(
  '/coupons/:couponId',
  staffOnly,
  validate(updateCouponSchema),
  couponController.updateCoupon
);

// Catalog management: flip the HSA/FSA eligibility flag on a single
// treatment without a code deploy (Phase 7.5 F12).
router.patch(
  '/treatments/:treatmentId/hsa-eligibility',
  staffOnly,
  catalogController.patchHsaEligibility
);

// Phase 8: provider profile management. Edits any subset of the profile
// fields (display name, bio, headshot, specialties, licensed states,
// years practicing, schools, credentials) and the profile_published gate
// that controls visibility on the public /providers/:id endpoint.
router.patch(
  '/providers/:providerId/profile',
  staffOnly,
  providerProfileController.patchProviderProfile
);

// Phase 9: visit work queue + scheduling. listAllVisits powers the
// admin Visits panel; adminUpdateVisit auto-provisions the video room
// when the status transitions to scheduled/in_progress and no URL is
// set yet.
router.get('/visits', staffOnly, visitController.listAllVisits);
router.patch(
  '/visits/:visitId',
  staffOnly,
  visitController.adminUpdateVisit
);

// Phase 10: lab work queue + ordering. listAllOrders powers the admin
// Labs panel; adminCreateOrder wires the stub vendor; adminUpdateOrder
// auto-stamps resulted_at on a status flip; adminAddResult appends an
// analyte result row.
router.get('/labs', staffOnly, labController.listAllOrders);
router.post('/labs', staffOnly, labController.adminCreateOrder);
router.patch(
  '/labs/:orderId',
  staffOnly,
  labController.adminUpdateOrder
);
router.post(
  '/labs/:orderId/results',
  staffOnly,
  labController.adminAddResult
);

// Phase 11: Acute / Urgent Care Line - staff work queue + triage update.
router.get('/urgent-visits', staffOnly, urgentController.listAllUrgent);
router.patch(
  '/urgent-visits/:visitId',
  staffOnly,
  urgentController.adminUpdateUrgent
);

// Phase 12: Pediatric Care - read-only admin view across every parent's
// dependents (with optional ?parentUserId filter).
router.get('/dependents', staffOnly, dependentController.adminListAll);

// Phase 13: Content & SEO layer - staff management of marketing pages.
// List/read drafts, create, update, and gate publication state through
// the dedicated publish/unpublish endpoints.
router.get('/content', staffOnly, contentController.listAdmin);
router.get('/content/:slug', staffOnly, contentController.adminGet);
router.post('/content', staffOnly, contentController.adminCreate);
router.patch('/content/:slug', staffOnly, contentController.adminUpdate);
router.post(
  '/content/:slug/publish',
  staffOnly,
  contentController.adminPublish
);
router.post(
  '/content/:slug/unpublish',
  staffOnly,
  contentController.adminUnpublish
);

module.exports = router;

'use strict';

// ============================================================================
// Route table aggregator.
// Mounts every feature router under /api. Phase 2 shipped authentication;
// Phase 4 added the clinical intake endpoint and the three Triad webhook
// receivers. Phase 13 adds the anonymous public content surface so search
// engines can fetch /api/content/:slug for the marketing pages.
// ============================================================================

const express = require('express');
const { query } = require('../db/query');
const authRoutes = require('./auth.routes');
const intakeRoutes = require('./intake.routes');
const checkoutRoutes = require('./checkout.routes');
const couponRoutes = require('./coupon.routes');
const checkinRoutes = require('./checkin.routes');
const catalogRoutes = require('./catalog.routes');
const providerProfileRoutes = require('./provider-profile.routes');
const publicRoutes = require('./public.routes');
const patientRoutes = require('./patient.routes');
const providerRoutes = require('./provider.routes');
const affiliateRoutes = require('./affiliate.routes');
const adminRoutes = require('./admin.routes');
const medicalNetworkWebhook = require('../webhooks/medical-network.webhook');
const pharmacyWebhook = require('../webhooks/pharmacy.webhook');
const stripeWebhook = require('../webhooks/stripe.webhook');
const clinicalWebhook = require('../webhooks/clinical.webhook');

const router = express.Router();

// Lightweight liveness probe for the load balancer. No database call so it
// stays green even during a brief database blip.
router.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok', service: 'pepnationrx-api' });
});

// Readiness probe: confirms the database is reachable before the instance is
// routed traffic. Returns 503 when the database cannot be queried, so an
// orchestrator holds traffic back until the dependency is healthy.
router.get('/health/ready', async (req, res) => {
  try {
    await query('SELECT 1');
    res.status(200).json({ status: 'ready', service: 'pepnationrx-api' });
  } catch (err) {
    res.status(503).json({ status: 'unavailable', service: 'pepnationrx-api' });
  }
});

// Feature routers.
router.use('/auth', authRoutes);
router.use('/intake', intakeRoutes);
router.use('/checkout', checkoutRoutes);
router.use('/coupons', couponRoutes);
// Public catalog read surface (Phase 7.5 F12). No auth; serves treatment
// listings and HSA / FSA eligibility flags to the storefront.
router.use('/catalog', catalogRoutes);
// Public provider profile surface (Phase 8). No auth; gated by
// profile_published in the controller.
router.use('/providers', providerProfileRoutes);
// Phase 13: public marketing content pages. No auth; gated by is_published
// in the controller so search engines can crawl every shipped page.
router.use('/content', publicRoutes);
// Check-in routes are mounted at '/' because their paths (/subscriptions/...
// and /checkins/...) are already fully qualified inside checkin.routes.js.
router.use('/', checkinRoutes);
router.use('/patient', patientRoutes);
router.use('/provider', providerRoutes);
router.use('/affiliate', affiliateRoutes);
router.use('/admin', adminRoutes);

// Triad webhook receivers plus the SteadyMD clinical decision callback.
// Each verifies a per-source HMAC signature internally.
router.use('/webhooks/medical-network', medicalNetworkWebhook);
router.use('/webhooks/pharmacy', pharmacyWebhook);
router.use('/webhooks/stripe', stripeWebhook);
router.use('/webhooks/clinical', clinicalWebhook);

module.exports = router;

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

const controller = require('../../src/controllers/content.controller');
const contentModel = require('../../src/models/content.model');

function fakeReq(overrides) {
  return Object.assign(
    {
      params: {},
      body: {},
      query: {},
      user: { id: 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee', role: 'admin' },
      ip: '127.0.0.1',
      get: function () { return null; },
