// ============================================================================
// content.service.js - PepNationRX public content client (Phase 13).
// ----------------------------------------------------------------------------
// Wraps the anonymous /api/content surface. Used by pnrx-content-page to
// hydrate marketing routes (/about, /how-it-works, /safety, /faq).
// ============================================================================

'use strict';

import { api } from './api.js';

// Fetch one published content page by slug. Throws ApiError on 404 or other
// non-2xx; the calling component renders an empty-state for those.
export function fetchPublicContent(slug) {
  return api.get('/api/content/' + encodeURIComponent(slug));
}

// ============================================================================
// seo.js - per-route SEO metadata helper (Phase 13).
// ----------------------------------------------------------------------------
// Single function that updates <title>, <meta name="description">, and the
// Open Graph title / description / image tags so every route can publish
// the right preview card to search engines and social-media unfurlers.
// The base index.html ships sensible defaults; this helper overrides them
// per route as the component mounts.
// ============================================================================

'use strict';

function upsertMeta(selector, attrName, attrValue, content) {
  let el = document.head.querySelector(selector);
  if (!el) {
    el = document.createElement('meta');
    el.setAttribute(attrName, attrValue);
    document.head.appendChild(el);
  }
  el.setAttribute('content', content);
}

// Update SEO meta tags for the current route. opts.title becomes the
// document title; opts.description fills the meta description and OG
// description; opts.ogImage replaces the OG image URL when provided.
// All fields are optional - omit any to leave the current value alone.
export function setSEO(opts) {
  const options = opts || {};
  if (options.title) {
    document.title = options.title + ' | PepNationRX';
    upsertMeta(
      'meta[property="og:title"]',
      'property',
      'og:title',
      options.title + ' | PepNationRX'
    );
  }
  if (options.description) {
    upsertMeta(
      'meta[name="description"]',
      'name',
      'description',
      options.description
    );
    upsertMeta(
      'meta[property="og:description"]',
      'property',
      'og:description',
      options.description
    );
  }
  if (options.ogImage) {
    upsertMeta(
      'meta[property="og:image"]',
      'property',
      'og:image',
      options.ogImage
    );
  }
}

// ============================================================================
// pnrx-content-page - editable marketing page surface (Phase 13).
// ----------------------------------------------------------------------------
// A custom element that fetches /api/content/:slug based on its `slug`
// attribute and renders the page through a tiny safe markdown subset
// (headings, bold, paragraphs, line breaks). On every successful load it
// also updates the document title and meta description through seo.js so
// every route publishes the right SEO surface.
//
// Usage:
//   <pnrx-content-page slug="about"></pnrx-content-page>
//
// The element is intentionally anonymous - no auth gate, no PHI handling.
// ============================================================================

'use strict';

import { PnrxComponent, escapeHtml } from '../core/component.js';
import { fetchPublicContent } from '../services/content.service.js';
import { setSEO } from '../seo.js';

// Render a small safe subset of markdown to HTML. Everything is escaped
// first; supported syntax:
//   - "## Heading" at start of line  -> <h2>
//   - "### Subheading" at start      -> <h3>
//   - "**bold**"                     -> <strong>
//   - blank line                     -> paragraph break
//   - lone newline inside a paragraph -> <br/>
// Anything else passes through as plain escaped text.
function renderSafeMarkdown(source) {
  if (typeof source !== 'string' || source.length === 0) return '';
  const blocks = source.split(/\n{2,}/);
  return blocks
    .map(function (block) {
      const trimmed = block.replace(/^\n+|\n+$/g, '');
      if (trimmed === '') return '';
      // Heading detection on the first line of the block.
      if (/^###\s+/.test(trimmed)) {
        const rest = trimmed.replace(/^###\s+/, '');
        return '<h3>' + renderInline(rest) + '</h3>';
      }
      if (/^##\s+/.test(trimmed)) {
        const rest = trimmed.replace(/^##\s+/, '');
        return '<h2>' + renderInline(rest) + '</h2>';
      }
      // Default: paragraph with single newlines as <br/>.
      const lines = trimmed.split('\n');
      const html = lines.map(renderInline).join('<br/>');
      return '<p>' + html + '</p>';
    })
    .filter(function (s) { return s !== ''; })
    .join('');
}

// Inline transform: escape first, then turn **text** into <strong>text</strong>.
// Because escapeHtml runs first, asterisks survive but any HTML the source
// supplied is inert.
function renderInline(text) {
  const escaped = escapeHtml(text);
  return escaped.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
}

export class PnrxContentPage extends PnrxComponent {
  constructor() {
    super();
    this.state = { status: 'loading', error: null, page: null };
  }

  static get observedAttributes() {
    return ['slug'];
  }

  attributeChangedCallback(name) {
    if (name === 'slug' && this.isConnected) {
      this.load();
    }
  }

  connectedCallback() {
    this._performRender();
    if (!this._hasLoaded) {
      this._hasLoaded = true;
      this.load();
    }
  }

  async load() {
    const slug = (this.getAttribute('slug') || '').trim();
    if (!slug) {
      this.setState({
        status: 'error',
        error: 'No Page Reference Supplied.',
      });
      return;
    }
    this.setState({ status: 'loading', error: null });
    try {
      const res = await fetchPublicContent(slug);
      const page = res && res.page ? res.page : null;
      if (!page) {
        this.setState({
          status: 'error',
          error: 'This Page Could Not Be Loaded.',
        });
        return;
      }
      // SEO meta tags for the route.
      setSEO({
        title: page.title,
        description: page.metaDescription || '',
        ogImage: page.metaOgImageUrl || '',
      });
      this.setState({ status: 'ready', page: page });
    } catch (err) {
      // 404 from the API => unpublished or missing; render a soft empty state.
      const message =
        err && err.status === 404
          ? 'This Page Is Not Available Yet.'
          : (err && err.message) || 'This Page Could Not Be Loaded.';
      this.setState({ status: 'error', error: message });
    }
  }

  render() {
    if (this.state.status === 'loading') {
      return (
        '<article class="pnrx-content">' +
        '<p class="pnrx-content__notice">Loading...</p>' +
        '</article>'
      );
    }
    if (this.state.status === 'error') {
      return (
        '<article class="pnrx-content pnrx-content--error">' +
        '<p class="pnrx-content__notice">' +
        escapeHtml(this.state.error || '') +
        '</p>' +
        '</article>'
      );
    }
    const page = this.state.page || {};
    const title = page.title || '';
    const body = renderSafeMarkdown(page.bodyMarkdown || '');
    return (
      '<article class="pnrx-content">' +
      '<h1 class="pnrx-content__title">' + escapeHtml(title) + '</h1>' +
      '<div class="pnrx-content__body">' + body + '</div>' +
      '</article>'
    );
  }
}

if (!customElements.get('pnrx-content-page')) {
  customElements.define('pnrx-content-page', PnrxContentPage);
}

